5	/// `dashboard.narrative.get`'s own response `data` (`openapi.yaml:1689-
6	/// 1736`) — decoded in full (`text`/`generatedAt`) even though [toDomain]
7	/// only ever reads [text], same "mirror the full contract" precedent
8	/// `DashboardAggregateDto` already sets for its own unused fields.
9	@JsonSerializable()
10	class DashboardNarrativeDto {
11	  const DashboardNarrativeDto({required this.text, required this.generatedAt});
12	
13	  final String text;
14	  final String generatedAt;
15	
16	  factory DashboardNarrativeDto.fromJson(Map<String, dynamic> json) =>
17	      _$DashboardNarrativeDtoFromJson(json);
18	
19	  Map<String, dynamic> toJson() => _$DashboardNarrativeDtoToJson(this);
20	
21	  /// Code Map: `toDomain()` returns only [text] as a plain `String` — no
22	  /// new entity, since the chart section only ever needs the narrative's
23	  /// own text (Intent: "one field").
24	  String toDomain() => text;
25	}
