8	/// Thin pass-through over [DashboardRemoteDataSource] (Code Map) — no
9	/// cache (Boundaries/Never: "cache the aggregate", AD-15 exclusion).
10	/// [DashboardAggregateDto.toDomain]'s own DTO->domain mapping lives on the
11	/// DTO itself, not here — this class only awaits the data source and
12	/// relays its result, same shape `ExportRepositoryImpl` already uses.
13	class DashboardRepositoryImpl implements DashboardRepository {
14	  DashboardRepositoryImpl({required this._remoteDataSource});
15	
16	  final DashboardRemoteDataSource _remoteDataSource;
17	
18	  @override
19	  Future<Either<Failure, DashboardAggregate>> getAggregate({
20	    required String period,
21	  }) async {
22	    final result = await _remoteDataSource.getAggregate(period: period);
23	    return result.map((dto) => dto.toDomain());
24	  }
25	
26	  /// spec-8-2 — same thin pass-through shape as [getAggregate] above.
27	  @override
28	  Future<Either<Failure, String>> getNarrative({required String period}) async {
29	    final result = await _remoteDataSource.getNarrative(period: period);
30	    return result.map((dto) => dto.toDomain());
31	  }
32	}
