11	/// Drives `DashboardChartSection`/Configurações' own "Sua evolução" chart
12	/// (spec-8-1, AD-12: a single data source, single fetch — exactly
13	/// `Resource<T>`'s own shape). A DI `registerLazySingleton` (Boundaries) —
14	/// long-lived like `AccountSettingsCubit`/`MeusRegistrosCubit`, so this
15	/// cubit's constructor subscription to [PendingEntryWriteTracker.
16	/// confirmedWrites] below stays live for the app's whole session, not just
17	/// while Configurações happens to be mounted (Boundaries: "recomputing on
18	/// each event (entry created on another tab while this one stays
19	/// mounted)").
20	///
21	/// Deliberately never caches a previous [load] result across calls
22	/// (Boundaries/Never: "cache the aggregate", AD-15 exclusion; FR-09:
23	/// "computed on demand, never stale") — every [load] re-emits
24	/// [ResourceLoading] first, same as `EntriesSearchCubit._search`.
25	class DashboardCubit extends Cubit<Resource<DashboardAggregate>> {
26	  DashboardCubit(this._repository, this._tracker)
27	    : super(const ResourceIdle()) {
28	    _confirmedSubscription = _tracker.confirmedWrites.listen((_) => load());
29	  }
30	
31	  final DashboardRepository _repository;
32	  final PendingEntryWriteTracker _tracker;
33	  late final StreamSubscription<({String tempId, Entry entry})>
34	  _confirmedSubscription;
35	
36	  /// A monotonic counter guarding against a stale in-flight [load] call's
37	  /// result landing after a newer one has already superseded it (e.g. a
38	  /// `confirmedWrites` event fires while `AccountSettingsScreen.initState`'s
39	  /// own [load] call is still in flight) — same generation-guard
40	  /// convention `EntriesSearchCubit._search`/`MeusRegistrosCubit.
41	  /// _loadFiltered` already use.
42	  int _generation = 0;
43	
44	  /// Boundaries: "`queryParameters: {'period': 'all'}` — fixed; no period
45	  /// selector exists anywhere in the product" — [load]'s one and only
46	  /// call to [DashboardRepository.getAggregate] always passes this.
47	  Future<void> load() async {
48	    final generation = ++_generation;
49	    emit(ResourceLoading());
50	    final result = await _repository.getAggregate(period: 'all');
51	    // Mirrors `EntriesSearchCubit._search`'s own guard: `close()` can race
52	    // this awaited call, and a newer `load()` (constructor-triggered
53	    // `confirmedWrites` event, or a second screen open) can have
54	    // superseded this one while it was in flight.
55	    if (isClosed || generation != _generation) {
56	      return;
57	    }
58	    result.match(
59	      (failure) => emit(ResourceError(failure)),
60	      (aggregate) => emit(ResourceData(aggregate)),
61	    );
62	  }
63	
64	  @override
65	  Future<void> close() async {
66	    await _confirmedSubscription.cancel();
67	    return super.close();
68	  }
69	}
