24	/// Same plain (non-mocktail) fake shape as
25	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
26	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
27	/// real stream the cubit (built from this fake, not mocked) actually
28	/// subscribes to. `biometricEnabledStream` is a plain broadcast stream, not
29	/// a `Stream.multi` replay wrapper (unlike the production repository) —
30	/// `AccountSettingsCubit`'s own constructor already reads
31	/// [currentBiometricEnabled] directly for its initial state, so no replay
32	/// machinery is needed for a fake with exactly one subscriber.
33	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
34	  bool _value = true;
35	  final _controller = StreamController<bool>.broadcast();
36	
37	  /// The next `setBiometricEnabled()` call's own result — defaults to a
38	  /// failure so a test must opt in to the success path explicitly, same
39	  /// convention as the cubit-level fake.
40	  Either<Failure, Unit> setBiometricEnabledResult = left(
41	    const Failure.malformedResponse(message: 'fake: not configured'),
42	  );
43	
44	  /// Lets a test hold `setBiometricEnabled()` unresolved, to observe
45	  /// `state.isSaving` mid-flight (review finding: the `Switch` must
46	  /// disable itself while a toggle is in flight).
47	  Completer<void>? setBiometricEnabledGate;
48	
49	  @override
50	  bool get currentBiometricEnabled => _value;
51	
52	  @override
53	  Stream<bool> get biometricEnabledStream => _controller.stream;
54	
55	  @override
56	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
57	
58	  @override
59	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
60	    final gate = setBiometricEnabledGate;
61	    if (gate != null) {
62	      await gate.future;
63	    }
64	    final previous = _value;
65	    _emit(enabled);
66	    final result = setBiometricEnabledResult;
67	    if (result.isLeft()) {
68	      _emit(previous);
69	    }
70	    return result;
71	  }
72	
73	  @override
74	  Future<void> dispose() => _controller.close();
75	
76	  void _emit(bool value) {
77	    _value = value;
78	    _controller.add(value);
79	  }
80	}
