82	/// spec-8-1 — a trivial fake [DashboardRepository]: this suite only needs
83	/// `AccountSettingsScreen.initState`'s own unconditional `dashboardCubit.
84	/// load()` call to resolve without throwing (`dashboard_cubit_test.dart`/
85	/// `dashboard_chart_section_test.dart` already cover the chart's own
86	/// behavior in isolation) — defaults to the zero-entries shape.
87	class _FakeDashboardRepository implements DashboardRepository {
88	  Either<Failure, DashboardAggregate> getAggregateResult = right(
89	    const DashboardAggregate(totalCount: 0, bucketCounts: []),
90	  );
91	
92	  /// spec-8-2 — defaults to a harmless success, same rationale
93	  /// [getAggregateResult] already gives: this suite's own job is the
94	  /// biometric toggle/chart wiring, not the narrative's own behavior
95	  /// (`dashboard_chart_section_test.dart`'s job).
96	  Either<Failure, String> getNarrativeResult = right('');
97	
98	  @override
99	  Future<Either<Failure, DashboardAggregate>> getAggregate({
100	    required String period,
101	  }) async => getAggregateResult;
102	
103	  @override
104	  Future<Either<Failure, String>> getNarrative({
105	    required String period,
106	  }) async => getNarrativeResult;
107	}
108	
109	/// A trivial fake `PendingEntryWriteTracker` — this suite never exercises
110	/// spec-8-1's own `confirmedWrites` recompute path, only that
111	/// `DashboardCubit`'s constructor subscription resolves without throwing.
112	class _UnusedPendingEntryWriteTracker implements PendingEntryWriteTracker {
113	  @override
114	  Future<Either<Failure, Entry>> create({
115	    required String content,
116	    required EntrySource source,
117	    int? mediaDurationSeconds,
118	  }) async => throw UnimplementedError('not expected to be called');
119	
120	  @override
121	  Future<void> retry(String tempId) async =>
122	      throw UnimplementedError('not expected to be called');
123	
124	  @override
125	  Stream<List<PendingEntryWrite>> get pendingWrites => const Stream.empty();
126	
127	  @override
128	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
129	      const Stream.empty();
130	
131	  @override
132	  Future<void> dispose() async {}
133	}
