135	/// Builds a fresh [DashboardCubit] and registers it for teardown — every
136	/// test below needs one to satisfy `AccountSettingsScreen`'s widened
137	/// constructor (spec-8-1), even the ones that otherwise only exercise the
138	/// biometric toggle. [repository] defaults to a fresh
139	/// [_FakeDashboardRepository] (the zero-entries shape); a caller that needs
140	/// to configure [_FakeDashboardRepository.getAggregateResult] *before*
141	/// `AccountSettingsScreen.initState`'s own `load()` call fires (review
142	/// finding: proving that call actually happens, not just that it doesn't
143	/// throw) passes its own instance in instead.
144	DashboardCubit _buildDashboardCubit({DashboardRepository? repository}) {
145	  final cubit = DashboardCubit(
146	    repository ?? _FakeDashboardRepository(),
147	    _UnusedPendingEntryWriteTracker(),
148	  );
149	  addTearDown(() => cubit.close());
150	  return cubit;
151	}
152	
153	/// spec-8-2 — mirrors [_buildDashboardCubit] above for the screen's own
154	/// second, independent cubit (Code Map).
155	DashboardNarrativeCubit _buildNarrativeCubit({DashboardRepository? repository}) {
156	  final cubit = DashboardNarrativeCubit(
157	    repository ?? _FakeDashboardRepository(),
158	    _UnusedPendingEntryWriteTracker(),
159	  );
160	  addTearDown(() => cubit.close());
161	  return cubit;
162	}
163	
164	/// `/configuracoes`'s `BackArrowHeader` does `context.go('/')`
165	/// (`back_arrow_header_test.dart`'s own rationale) — needs a real
166	/// `GoRouter` ancestor to resolve, hence this minimal two-route wrapper
167	/// rather than a bare `MaterialApp`.
168	GoRouter _routerWith(Widget screen) {
169	  return GoRouter(
170	    initialLocation: '/configuracoes',
171	    routes: [
172	      GoRoute(path: '/', builder: (context, state) => const Text('Home')),
173	      GoRoute(path: '/configuracoes', builder: (context, state) => screen),
174	    ],
175	  );
176	}
177	
178	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
179	/// pair and pumps the real screen around it, registering both for cleanup.
180	///
181	/// Deliberately constructed *inside* each `testWidgets` body (via this
182	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
183	/// `package:test`'s own per-test zone, a different zone than the one
184	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
185	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
186	/// subscription to the repository's stream, set up in its constructor)
187	/// created in that outer zone does not reliably get its pending events
188	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
189	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
190	/// widget never rebuilt, no matter how many `pump()` calls followed.
191	/// Constructing the cubit here, inside the same zone `tester.pump()`
192	/// drains, avoids the mismatch entirely.
193	Future<(_FakeAccountSettingsRepository, AccountSettingsCubit)> _pumpScreen(
194	  WidgetTester tester,
195	) async {
196	  final fakeRepository = _FakeAccountSettingsRepository();
197	  final cubit = AccountSettingsCubit(fakeRepository);
198	  addTearDown(() => cubit.close());
199	  addTearDown(fakeRepository.dispose);
200	
201	  final router = _routerWith(
202	    AccountSettingsScreen(
203	      cubit: cubit,
204	      dashboardCubit: _buildDashboardCubit(),
205	      narrativeCubit: _buildNarrativeCubit(),
206	    ),
207	  );
208	  addTearDown(router.dispose);
209	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
210	
211	  return (fakeRepository, cubit);
212	}
213	
214	/// Proves spec-2-4's Acceptance Criteria directly against the real screen
215	/// widget: "shows only the biometric toggle" (minimal), the toggle mirrors
216	/// the cubit's state, tapping it drives `toggleBiometric()`, and a failed
217	/// toggle's error message renders inline — `app_router_test.dart` already
218	/// proves the screen is *reachable*; this suite proves its own rendering
219	/// and interaction in isolation.
220	void main() {
221	  testWidgets(
222	    // Review finding (round 2): renamed from "...exactly one switch — no '
223	    // other content (AC: shows only the biometric toggle)" — spec-8-1 now
224	    // also renders the "Sua evolução" chart section on this same screen,
225	    // so that title no longer reflects what the screen actually shows.
226	    'shows the biometric toggle and the dashboard chart section',
227	    (tester) async {
228	      await _pumpScreen(tester);
229	
230	      expect(find.byType(BackArrowHeader), findsOneWidget);
231	      expect(find.text('Configurações'), findsOneWidget);
232	      expect(find.byType(Switch), findsOneWidget);
233	      expect(find.text('Entrar com biometria'), findsOneWidget);
234	      expect(find.text('Sua evolução'), findsOneWidget);
235	    },
236	  );
237	
238	  testWidgets(
239	    'the switch mirrors currentBiometricEnabled (true) at construction',
240	    (tester) async {
241	      await _pumpScreen(tester);
242	
243	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
244	      expect(switchWidget.value, isTrue);
245	    },
246	  );
247	
248	  testWidgets(
249	    'a false currentBiometricEnabled (already fetched before the screen '
250	    'opened) renders the switch off',
251	    (tester) async {
252	      final fakeRepository = _FakeAccountSettingsRepository().._emit(false);
253	      final cubit = AccountSettingsCubit(fakeRepository);
254	      addTearDown(() => cubit.close());
255	      addTearDown(fakeRepository.dispose);
256	
257	      final router = _routerWith(
258	        AccountSettingsScreen(
259	          cubit: cubit,
260	          dashboardCubit: _buildDashboardCubit(),
261	          narrativeCubit: _buildNarrativeCubit(),
262	        ),
263	      );
264	      addTearDown(router.dispose);
265	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
266	
267	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
268	      expect(switchWidget.value, isFalse);
269	    },
270	  );
271	
272	  testWidgets(
273	    'tapping the switch calls toggleBiometric() with the requested value and '
274	    'flips the rendered switch — no error band on success',
275	    (tester) async {
276	      final (fakeRepository, _) = await _pumpScreen(tester);
277	      fakeRepository.setBiometricEnabledResult = right(unit);
278	
279	      await tester.tap(find.byType(Switch));
280	      await tester.pumpAndSettle();
281	
282	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
283	      expect(switchWidget.value, isFalse);
284	      // No error text rendered — only the label and the back-arrow title.
285	      expect(find.textContaining('conexão'), findsNothing);
286	    },
287	  );
288	
289	  testWidgets(
290	    'a failed toggle reverts the switch and shows the Failure\'s message '
291	    'inline, below the toggle row',
292	    (tester) async {
293	      final (fakeRepository, _) = await _pumpScreen(tester);
294	      fakeRepository.setBiometricEnabledResult = left(
295	        const Failure.networkTimeout(message: 'Sem conexão'),
296	      );
297	
298	      await tester.tap(find.byType(Switch));
299	      await tester.pumpAndSettle();
300	
301	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
302	      expect(switchWidget.value, isTrue);
303	      expect(find.text('Sem conexão'), findsOneWidget);
304	    },
305	  );
306	
307	  testWidgets('the switch disables itself while a toggle is in flight, so a '
308	      'double-tap can never start a second, overlapping call (review '
309	      'finding)', (tester) async {
310	    final (fakeRepository, _) = await _pumpScreen(tester);
311	    fakeRepository.setBiometricEnabledResult = right(unit);
312	    fakeRepository.setBiometricEnabledGate = Completer<void>();
313	
314	    await tester.tap(find.byType(Switch));
315	    await tester.pump();
316	
317	    var switchWidget = tester.widget<Switch>(find.byType(Switch));
318	    expect(switchWidget.onChanged, isNull);
319	
320	    fakeRepository.setBiometricEnabledGate!.complete();
321	    await tester.pumpAndSettle();
322	
323	    switchWidget = tester.widget<Switch>(find.byType(Switch));
324	    expect(switchWidget.onChanged, isNotNull);
325	    expect(switchWidget.value, isFalse);
326	  });
327	
328	  testWidgets('a stale error from a previous visit is cleared when the screen '
329	      '(re)mounts — AccountSettingsCubit is a DI singleton that outlives any '
330	      'single visit, so a failed toggle\'s message must not still be '
331	      'showing on a later, unrelated visit (review finding)', (tester) async {
332	    final (fakeRepository, cubit) = await _pumpScreen(tester);
333	    fakeRepository.setBiometricEnabledResult = left(
334	      const Failure.networkTimeout(message: 'Sem conexão'),
335	    );
336	
337	    await tester.tap(find.byType(Switch));
338	    await tester.pumpAndSettle();
339	    expect(find.text('Sem conexão'), findsOneWidget);
340	
341	    // Simulates leaving and returning to Configurações: a brand new
342	    // `AccountSettingsScreen` (and its own `State`, calling `initState`
343	    // again) built around the SAME, still-singleton cubit — exactly
344	    // what a fresh `GoRoute.builder` call would produce.
345	    final router = _routerWith(
346	      AccountSettingsScreen(
347	        cubit: cubit,
348	        dashboardCubit: _buildDashboardCubit(),
349	        narrativeCubit: _buildNarrativeCubit(),
350	      ),
351	    );
352	    addTearDown(router.dispose);
353	    await tester.pumpWidget(MaterialApp.router(routerConfig: router));
354	
355	    expect(find.text('Sem conexão'), findsNothing);
356	    // The toggle's own confirmed value is untouched by the error clear.
357	    final switchWidget = tester.widget<Switch>(find.byType(Switch));
358	    expect(switchWidget.value, isTrue);
359	  });
