23	/// Same shape as `pending_write_sync_e2e_test.dart`'s/`export_flow_e2e_test.
24	/// dart`'s own fake — only the transport boundary is faked, everything
25	/// above it (URL building, both real interceptors, `ApiClient`'s mapping,
26	/// `DashboardAggregateDto`'s decode) is the genuine production wiring.
27	class _FakeHttpClientAdapter implements HttpClientAdapter {
28	  final List<RequestOptions> requests = [];
29	  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];
30	
31	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
32	    _queue.add((statusCode: statusCode, body: body));
33	  }
34	
35	  void queueErrorResponse(String code, String message) {
36	    final status = switch (code) {
37	      'VALIDATION_ERROR' => 400,
38	      'NETWORK_TIMEOUT' => 504,
39	      _ => 500,
40	    };
41	    queueJsonResponse(status, {
42	      'code': code,
43	      'message': message,
44	      'retryable': RetryInterceptor.retryableCodes.contains(code),
45	    });
46	  }
47	
48	  @override
49	  Future<ResponseBody> fetch(
50	    RequestOptions options,
51	    Stream<Uint8List>? requestStream,
52	    Future<void>? cancelFuture,
53	  ) async {
54	    requests.add(options);
55	    if (_queue.isEmpty) {
56	      throw StateError(
57	        'No queued response for ${options.method} ${options.path}',
58	      );
59	    }
60	    final next = _queue.removeAt(0);
61	    return ResponseBody.fromString(
62	      jsonEncode(next.body),
63	      next.statusCode,
64	      headers: {
65	        Headers.contentTypeHeader: [Headers.jsonContentType],
66	      },
67	    );
68	  }
69	
70	  @override
71	  void close({bool force = false}) {}
72	}
