120	/// Waits for [cubit]'s state to satisfy [match] via its own `stream`,
121	/// rather than a fixed real-time sleep — same rationale/shape
122	/// `export_flow_e2e_test.dart`'s own `_waitForState` gives: `load()`'s real
123	/// `dio` round trip (and, in the confirmedWrites test below, a second one
124	/// triggered with no test code calling `load()` itself) isn't guaranteed to
125	/// have landed by any particular `pump()`/microtask count.
126	Future<void> _waitForState(
127	  DashboardCubit cubit,
128	  bool Function(Resource<DashboardAggregate>) match,
129	) {
130	  if (match(cubit.state)) {
131	    return Future.value();
132	  }
133	  return cubit.stream.firstWhere(match).timeout(const Duration(seconds: 10));
134	}
