4	/// Mocks `SystemChannels.accessibility` directly — the channel
5	/// `SemanticsService.sendAnnouncement` sends on — so a test can assert on
6	/// the real announcement content instead of only reading visible `Text`
7	/// widgets (which would still pass even if a `_announce()` call were
8	/// deleted or its guard inverted). Extracted from
9	/// `vault_lock_screen_test.dart`'s own `AC3` group, which first proved
10	/// this pattern; reused by `insertion_modal_test.dart`.
11	List<String> interceptAnnouncements(WidgetTester tester) {
12	  final messages = <String>[];
13	  tester.binding.defaultBinaryMessenger.setMockDecodedMessageHandler<dynamic>(
14	    SystemChannels.accessibility,
15	    (dynamic call) async {
16	      final event = call as Map<dynamic, dynamic>;
17	      if (event['type'] == 'announce') {
18	        final data = event['data'] as Map<dynamic, dynamic>;
19	        messages.add(data['message'] as String);
20	      }
21	      return null;
22	    },
23	  );
24	  addTearDown(
25	    () => tester.binding.defaultBinaryMessenger
26	        .setMockDecodedMessageHandler<dynamic>(
27	          SystemChannels.accessibility,
28	          null,
29	        ),
30	  );
31	  return messages;
32	}
