105	/// Collects every state the cubit emits for the duration of [act] — same
106	/// helper `dashboard_cubit_test.dart` already documents.
107	Future<List<Resource<String>>> _emittedDuring(
108	  DashboardNarrativeCubit cubit,
109	  FutureOr<void> Function() act,
110	) async {
111	  final emitted = <Resource<String>>[];
112	  final subscription = cubit.stream.listen(emitted.add);
113	  await act();
