115	  // for delivery but not yet dispatched to this listener — same rationale
116	  // `dashboard_cubit_test.dart`'s own `_emittedDuring` gives.
117	  await Future<void>.delayed(Duration.zero);
118	  await subscription.cancel();
119	  return emitted;
120	}
